window.itemFitsType = function(item, type){
  if(!item) return false;
  if(item.type === type) return true;
  if(Array.isArray(item.positions) && item.positions.includes(type)) return true;
  return false;
};

window.getItemsByType = function(type){
  return window.ITEMS.filter(i => window.itemFitsType(i, type));
};

window.getItemById = function(id){
  return window.ITEMS.find(i => i.id === id) || null;
};

window.itemFamily = function(name){
  if(!name) return "";
  const POS_WORDS = /\b(Upper|Middle|Lower|Garment|Weapon|Armor|Shield|Shoes|Set)\b/gi;
  return name
    .replace(POS_WORDS, " ")
    .replace(/\+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
};

